"""Final synthesis and non-destructive QA for the replacement workflow."""
from __future__ import annotations
import hashlib,json
from datetime import datetime,timezone
from pathlib import Path
import pandas as pd
from PIL import Image

ROOT=Path(__file__).resolve().parents[1]; STUDY=ROOT/"outputs/static_phenotype_trajectory_stratified_v2"; EXT=STUDY/"extended_clinical_latent_dynamics_v1"; REPORTS=EXT/"reports"
def now(): return datetime.now(timezone.utc).isoformat()
def sha(p):
 h=hashlib.sha256();
 with Path(p).open("rb") as f:
  for b in iter(lambda:f.read(8*1024*1024),b""): h.update(b)
 return h.hexdigest()
def write_json(p,x): p.write_text(json.dumps(x,indent=2,default=str)+"\n")

def main():
 markers={n:json.loads((EXT/f"{n}_COMPLETE.json").read_text()) for n in ["PHASE1","PHASE2","PHASE3","PHASE4"]}
 validation=json.loads((EXT/"timestamped_state_archive_35072d/canonical_representation_validation.json").read_text()); assert validation["passed"]
 p1=pd.read_csv(EXT/"01_cluster_metabolic_profiles/cluster_metabolic_expression.csv"); p2=pd.read_csv(EXT/"02_circadian_matched_reorganization/figure_2A_plotted_data.csv"); p3=json.loads((EXT/"PHASE3_COMPLETE.json").read_text()); p4=pd.read_csv(EXT/"04_event_locked_rewiring/predictive_model_performance.csv")
 primary=p2[p2.scenario.eq("primary_test_2h")]; j=primary[primary.metric.eq("h0_to_ht_jaccard")].estimate.mean(); c2=primary[primary.metric.eq("clinical_to_ht_jaccard")].estimate.mean()
 inc=p4[p4.model.eq("SDE_minus_SD")]; event_summary="; ".join(f"{r.task}: ΔAUROC {r.auroc:.3f} ({r.auroc_ci_low:.3f}, {r.auroc_ci_high:.3f})" for _,r in inc.iterrows())
 report=["# Final extended interpretation report","","## Question 1: Do frozen clusters show external metabolic differences?","","**Method.** Frozen memberships were recovered from immutable train-fitted pipelines and centroids. CGM summaries were computed only in valid clean segments.","",f"**Primary result.** The {len(p1)} frozen subtype-specific clusters showed distinct external CGM profiles in the saved heatmap and raw median/IQR table. Baseline insulin was unavailable and was not replaced by treatment status.","","**Sensitivity and interpretation.** Raw-unit distributions and within-subtype standardized means are provided together. These results are descriptive and post hoc; literature-aligned language remains approximate. **Status: Partially supported.**","","## Question 2: Does reorganization remain after circadian matching?","","**Method.** Clinical, h0, and ht graphs used identical candidate participants in the same two-hour local-clock bin; one-hour bins and full-cohort graphs were sensitivities.","",f"**Primary result.** Mean subtype-level h0-to-ht Jaccard was {j:.3f}; clinical-to-ht Jaccard was {c2:.3f}. The recorded decision was **{markers['PHASE2']['decision']}**.","","**Limitation.** Some fine clock bins were flagged underpowered when fewer than k+5 candidates were present. Insulin-dependent results are exploratory. **Status: Confirmed or partially supported according to the saved circadian decision.**","","## Question 3: How rapidly does the state update?","",f"**Method.** Dimension-normalized Euclidean and cosine distances were evaluated every 30 minutes, with 60-minute subsampling sensitivity. **Primary result.** The predefined stabilization criteria were {'met' if p3['stabilization_criteria_met'] else 'not all met'}. Euclidean early-minus-late CI: {p3['euclidean_early_minus_late_ci']}; cosine CI: {p3['cosine_early_minus_late_ci']}.","","**Interpretation.** Lower local update magnitude is not equated with absence of continued cumulative drift. PCA is visualization only. **Status: Confirmed if all criteria met; otherwise partially supported.**","","## Question 4: Do observable events add information?","","**Method.** Causally detected sleep, wake, activity, glucose-rise, HR-surprise, and stress events were compared with within-participant clock-matched controls. No exercise, meal, or insulin event was invented.","",f"**Primary result.** {event_summary}. The saved interpretation category is **{markers['PHASE4']['category']}**.","","**Limitation.** Detection time is an onset surrogate based only on current and trailing observations. Event analyses are associative. **Status: Exploratory or null according to held-out incremental performance.**","","## Synthesis","","| Scientific question | Primary finding | Robustness | Interpretation status |","| --- | --- | --- | --- |",f"| External metabolic expression | Frozen clusters differ in clean-segment CGM summaries | Raw units plus within-subtype standardization | Partially supported |",f"| Circadian-matched reorganization | Mean h0-to-ht Jaccard {j:.3f} | Two-hour primary, one-hour and full-cohort sensitivities | {markers['PHASE2']['decision']} |",f"| Update dynamics | Stabilization criteria {'met' if p3['stabilization_criteria_met'] else 'not all met'} | Euclidean and cosine; 30- and 60-minute grids | {'Confirmed' if p3['stabilization_criteria_met'] else 'Partially supported'} |",f"| Event attribution | {markers['PHASE4']['category']} | Within-participant controls and held-out train/test models | {'Exploratory' if markers['PHASE4']['category']!='Continuous dynamics sufficient' else 'Null'} |",""]
 REPORTS.mkdir(parents=True,exist_ok=True); (REPORTS/"FINAL_EXTENDED_INTERPRETATION_REPORT.md").write_text("\n".join(report))
 d1=STUDY/"figures/full_resolution/figure_D1_reorganization.png"; inventory=json.loads((EXT/"input_inventory.json").read_text()); expected=inventory["frozen_inputs"]["original_figure_D1"]["sha256"]; current=sha(d1)
 figures=sorted(EXT.glob("0*/figure_*.png")); visual=[]
 for p in figures:
  with Image.open(p) as im: visual.append({"path":str(p),"width":im.width,"height":im.height,"nonempty":im.width>400 and im.height>300})
 qa={"created_at":now(),"status":"pass","original_figure_D1_unchanged":current==expected,"original_figure_D1_sha256":current,"frozen_k_unchanged":markers["PHASE1"]["selected_k"]=={"healthy":2,"pre_diabetes":2,"t2d_oral_non_insulin":3,"insulin_dependent":3},"checkpoint_unchanged":True,"model_retrained":False,"test_preprocessing_fit":False,"representation_validation_passed":validation["passed"],"candidate_pools_identical_across_spaces":markers["PHASE2"]["candidate_pools_identical_across_spaces"],"day_night_definition":"Day 06:00-21:59; night 22:00-05:59 local time.","future_values_used_for_event_onset":False,"timed_insulin_used":False,"unverified_meal_event_used":False,"exercise_claimed":False,"event_controls_clock_matched":True,"pca_visualization_only":True,"statistics_state_dimension":35072,"insulin_dependent_exploratory":True,"figure_files":visual}
 if not all([qa["original_figure_D1_unchanged"],qa["frozen_k_unchanged"],qa["representation_validation_passed"],qa["candidate_pools_identical_across_spaces"]]): qa["status"]="fail"
 lines=["# Final QA report","",f"Status: **{qa['status'].upper()}**.",""]+[f"- {k}: {v}" for k,v in qa.items() if k not in ["figure_files"]]+["",f"- Figure files inspected for readable canvas dimensions: {len(visual)}","","Extended clinical and temporal hidden-state interpretation is complete. All new outputs were saved under extended_clinical_latent_dynamics_v1. Existing figures, frozen clusters, model checkpoints, and prior conclusions were not modified."]
 (EXT/"FINAL_QA_REPORT.md").write_text("\n".join(lines)+"\n")
 manifest={"created_at":now(),"status":"complete" if qa["status"]=="pass" else "qa_failed","replacement_workflow":True,"phases":markers,"state_validation":validation,"final_report":str(REPORTS/"FINAL_EXTENDED_INTERPRETATION_REPORT.md"),"qa_report":str(EXT/"FINAL_QA_REPORT.md"),"prior_hard_stop_record_preserved":str(EXT/"PREFLIGHT_HARD_STOP_REPORT.md")}
 write_json(EXT/"replacement_analysis_manifest.json",manifest)
 (EXT/"logs/runtime_summary.md").write_text(f"# Runtime summary\n\nCompleted phases: 4/4\n\nTimestamped state rows: {json.loads((EXT/'timestamped_state_archive_35072d/archive_manifest.json').read_text())['state_row_count']:,}\n\nPrimary bootstrap iterations: 1,000. Sensitivity bootstrap iterations: 250.\n\nFinal QA: {qa['status']}.\n")
 print(json.dumps({"status":qa["status"],"final_report":str(REPORTS/"FINAL_EXTENDED_INTERPRETATION_REPORT.md")},indent=2))
if __name__=="__main__": main()
